events.body:
There is something I noticed, that is not introduced by this PR and idk if it is worth addressing, but anyway, will drop some code suggestion here in case you want to take it.

The new `IncIndex`/`DecIndex`/`SetRangeEnd` follow the file's assert-side convention `AssertLockHeld(cs_desc_man)`, so it does not `LOCK`. But then they call call `CanGetAddresses()`, which has a `LOCK` and then `CanGetAddresses()` in calls `HavePrivateKeys()`, which has another `LOCK`. So each mutation acquires `cs_desc_man` ~4 times recursively.
Tbh I am not sure how bad recursive locks are or if they are even bad, it just feels weird and worth reporting.

I though that we could just have some "internal" functions that assumes the `LOCK` is acquired but does not acquire it again. And then have public methods that just acquire the `LOCK` and rely on the internal method for the logic.
This way member methods like `IncIndex`, etc. that already have the `LOCK` can rely on the internal methods directly without taking the `LOCK` in a recursive way. This reduces the recursive locks from ~4 to 0 (the `LOCK` is only acquired once).

As said, this is probably not worth a PR, but could be added as another commit here if you think is worth.

<details>
<summary>code suggestion</summary>

```diff
$ git diff
diff --git a/src/wallet/scriptpubkeyman.cpp b/src/wallet/scriptpubkeyman.cpp
index 904593af26..c8246a07cc 100644
--- a/src/wallet/scriptpubkeyman.cpp
+++ b/src/wallet/scriptpubkeyman.cpp
@@ -875,9 +875,9 @@ void DescriptorScriptPubKeyMan::IncIndex()
 {
     AssertLockHeld(cs_desc_man);
 
-    const auto old_can = CanGetAddresses();
+    const auto old_can = CanGetAddressesInternal();
     m_wallet_descriptor.IncNext();
-    const auto new_can = CanGetAddresses();
+    const auto new_can = CanGetAddressesInternal();
     if (old_can != new_can) {
         NotifyCanGetAddressesChanged();
     }
@@ -887,9 +887,9 @@ void DescriptorScriptPubKeyMan::DecIndex()
 {
     AssertLockHeld(cs_desc_man);
 
-    const auto old_can = CanGetAddresses();
+    const auto old_can = CanGetAddressesInternal();
     m_wallet_descriptor.DecNext();
-    const auto new_can = CanGetAddresses();
+    const auto new_can = CanGetAddressesInternal();
     if (old_can != new_can) {
         NotifyCanGetAddressesChanged();
     }
@@ -899,9 +899,9 @@ void DescriptorScriptPubKeyMan::SetRangeEnd(int32_t end)
 {
     AssertLockHeld(cs_desc_man);
 
-    const auto old_can = CanGetAddresses();
+    const auto old_can = CanGetAddressesInternal();
     m_wallet_descriptor.SetEnd(end);
-    const auto new_can = CanGetAddresses();
+    const auto new_can = CanGetAddressesInternal();
     if (old_can != new_can) {
         NotifyCanGetAddressesChanged();
     }
@@ -1247,22 +1247,34 @@ bool DescriptorScriptPubKeyMan::IsHDEnabled() const
     return m_wallet_descriptor.descriptor->IsRange();
 }
 
-bool DescriptorScriptPubKeyMan::CanGetAddresses(bool internal) const
+bool DescriptorScriptPubKeyMan::CanGetAddressesInternal() const
 {
     // We can only give out addresses from descriptors that are single type (not combo), ranged,
     // and either have cached keys or can generate more keys (ignoring encryption)
-    LOCK(cs_desc_man);
+    AssertLockHeld(cs_desc_man);
     return m_wallet_descriptor.descriptor->IsSingleType() &&
            m_wallet_descriptor.descriptor->IsRange() &&
-           (HavePrivateKeys() || m_wallet_descriptor.GetNext() < m_wallet_descriptor.GetEnd() || m_wallet_descriptor.descriptor->CanSelfExpand());
+           (HavePrivateKeysInternal() || m_wallet_descriptor.GetNext() < m_wallet_descriptor.GetEnd() || m_wallet_descriptor.descriptor->CanSelfExpand());
 }
 
-bool DescriptorScriptPubKeyMan::HavePrivateKeys() const
+bool DescriptorScriptPubKeyMan::CanGetAddresses(bool internal) const
 {
     LOCK(cs_desc_man);
+    return CanGetAddressesInternal();
+}
+
+bool DescriptorScriptPubKeyMan::HavePrivateKeysInternal() const
+{
+    AssertLockHeld(cs_desc_man);
     return m_map_keys.size() > 0 || m_map_crypted_keys.size() > 0;
 }
 
+bool DescriptorScriptPubKeyMan::HavePrivateKeys() const
+{
+    LOCK(cs_desc_man);
+    return HavePrivateKeysInternal();
+}
+
 bool DescriptorScriptPubKeyMan::HaveCryptedKeys() const
 {
     LOCK(cs_desc_man);
@@ -1333,7 +1345,7 @@ std::unique_ptr<FlatSigningProvider> DescriptorScriptPubKeyMan::GetSigningProvid
         m_map_signing_providers[index] = *out_keys;
     }
 
-    if (HavePrivateKeys() && include_private) {
+    if (HavePrivateKeysInternal() && include_private) {
         FlatSigningProvider master_provider;
         master_provider.keys = GetKeys();
         m_wallet_descriptor.descriptor->ExpandPrivate(index, master_provider, *out_keys);
diff --git a/src/wallet/scriptpubkeyman.h b/src/wallet/scriptpubkeyman.h
index 809a999d26..73d8600bf3 100644
--- a/src/wallet/scriptpubkeyman.h
+++ b/src/wallet/scriptpubkeyman.h
@@ -344,6 +344,12 @@ protected:
     void DecIndex() EXCLUSIVE_LOCKS_REQUIRED(cs_desc_man);
     void SetRangeEnd(int32_t end) EXCLUSIVE_LOCKS_REQUIRED(cs_desc_man);
 
+    bool CanGetAddressesInternal() const EXCLUSIVE_LOCKS_REQUIRED(cs_desc_man);
+    bool HavePrivateKeysInternal() const EXCLUSIVE_LOCKS_REQUIRED(cs_desc_man);
+
     //! Same as 'TopUp' but designed for use within a batch transaction context
     bool TopUpWithDB(WalletBatch& batch, unsigned int size = 0);
 
```

</details>

